CREATE TABLE teacher_rates(tenant_id TEXT NOT NULL REFERENCES tenants(id),id TEXT NOT NULL,teacher_id TEXT NOT NULL,course_type_id TEXT NOT NULL,format TEXT NOT NULL,rate_basis TEXT NOT NULL DEFAULT 'legacy',rate INTEGER NOT NULL CHECK(typeof(rate)='integer' AND rate>=0),effective_from TEXT NOT NULL,effective_to TEXT NOT NULL,created_at INTEGER NOT NULL,created_by TEXT NOT NULL,updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,deleted_at INTEGER,PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,teacher_id) REFERENCES teachers(tenant_id,id),FOREIGN KEY(tenant_id,course_type_id) REFERENCES course_types(tenant_id,id));
